#!/bin/bash
source /private/tmp/claude-501/-Users-kyle-Developer-grantiva-cli/b9f2e919-f7a5-4b94-a1bc-202f523560f4/scratchpad/cov3-android/env.sh
cd $P; KA2="bash $S/tools/ka2.sh"; APK=$S/app-free-debug.apk
# L03: GPU host AVD
rec B2-L03 "\$GRANTIVA emulator teardown --serial emulator-5556; \$GRANTIVA emulator delete --name cov3-android-2; \$GRANTIVA emulator ensure --name cov3-android-2 --no-boot; sed -i '' -e 's/^hw.gpu.mode=.*/hw.gpu.mode=host/' -e 's/^hw.gpu.enabled=.*/hw.gpu.enabled=yes/' ~/.android/avd/cov3-android-2.avd/config.ini; grep hw.gpu ~/.android/avd/cov3-android-2.avd/config.ini; \$GRANTIVA emulator ensure --name cov3-android-2; \$GRANTIVA build install --no-build --app-file $APK --device emulator-5556 --no-launch; grep hw.gpu ~/.android/avd/cov3-android/config.ini 2>/dev/null || grep hw.gpu ~/.android/avd/cov3-android.avd/config.ini"
for i in 1 2 3; do rec B2-L03 "bash $S/tools/seedmany2.sh emulator-5556 gpu-f$i --snapshot full; grep -c 'POST .*/actions' $S/sm-gpu-f$i/client.log; grep -m2 'POST .*/actions' $S/sm-gpu-f$i/client.log | cut -c1-260"; done
for i in 1 2 3; do rec B2-L03 "bash $S/tools/seedmany2.sh emulator-5554 sw-f$i --snapshot full; grep -m2 'POST .*/actions' $S/sm-sw-f$i/client.log | cut -c1-260"; done
# concurrent runs
rec AND-062 "\$GRANTIVA run --device emulator-5554 --no-build --flow .maestro/01-browse.yaml > $E/AND-062/a.out 2> $E/AND-062/a.err & a=\$!; \$GRANTIVA run --device emulator-5556 --no-build --flow .maestro/05-category.yaml > $E/AND-062/b.out 2> $E/AND-062/b.err & b=\$!; wait \$a; echo a-exit=\$?; wait \$b; echo b-exit=\$?; grep -E '^[✓✗] ' $E/AND-062/a.err $E/AND-062/b.err"
# two keep-alive sessions, hierarchy newest / --udid, runner stop lists both
rec AND-052 "$KA2 $E/AND-052/ka1 emulator-5554 .maestro/01-browse.yaml; sleep 2; $KA2 $E/AND-052/ka2 emulator-5556 .maestro/05-category.yaml; ls /tmp/grantiva-sessions; \$GRANTIVA hierarchy | grep -o 'text=\"\\(Plan Visit\\|Mono Lake\\)\"' | sort -u"
rec AND-056 "\$GRANTIVA hierarchy --udid emulator-5554 | grep -o 'text=\"\\(Plan Visit\\|Mono Lake\\)\"' | sort -u; \$GRANTIVA hierarchy --udid emulator-5556 | grep -o 'text=\"\\(Plan Visit\\|Mono Lake\\)\"' | sort -u"
rec N2-05 "\$GRANTIVA runner stop --json; echo exit=\$?; sleep 3; ls /tmp/grantiva-sessions; for p in \$(cat $E/AND-052/ka1.pid) \$(cat $E/AND-052/ka2.pid); do kill -0 \$p 2>/dev/null && echo \$p-alive || echo \$p-exited; done"
# orphan forwards
rec AND-064 "adb -s emulator-5556 forward tcp:0 tcp:6790; adb -s emulator-5554 forward tcp:0 tcp:6790; adb forward --list; \$GRANTIVA run --device emulator-5554 --no-build --flow .maestro/01-browse.yaml >/dev/null 2>&1; echo exit=\$?; adb forward --list; adb -s emulator-5556 forward --remove-all"
# teardown with a runner session (K15)
rec B2-K15 "\$GRANTIVA runner start --detach --device emulator-5556; rp=\$(python3 -I -c \"import json;print(json.load(open('.grantiva/session.json'))['pid'])\"); echo runner=\$rp; adb forward --list; \$GRANTIVA emulator teardown --serial emulator-5556 --json; echo exit=\$?; sleep 2; kill -0 \$rp 2>/dev/null && echo runner-alive || echo runner-gone; ls .grantiva/session.json 2>&1; ls /tmp/grantiva-sessions; adb forward --list; adb devices"
# AND-013: recorded pid dead, AVD re-booted by hand
rec AND-013 "\$GRANTIVA emulator ensure --name cov3-android-2; ep=\$(python3 -I -c \"import json,os;print([r['pid'] for r in json.load(open(os.path.expanduser('~/.grantiva/android/started.json'))) if r['serial']=='emulator-5556'][0])\"); echo recorded-pid=\$ep; kill -9 \$ep; sleep 3; nohup $ANDROID_HOME/emulator/emulator -avd cov3-android-2 -port 5556 -no-snapshot-save -no-boot-anim > $S/hand-5556.log 2>&1 & echo \$! > $S/hand-5556.pid; adb -s emulator-5556 wait-for-device; for i in \$(seq 1 90); do [ \"\$(adb -s emulator-5556 shell getprop sys.boot_completed 2>/dev/null | tr -d '\\r')\" = 1 ] && break; sleep 2; done; echo hand-booted pid=\$(cat $S/hand-5556.pid); cat ~/.grantiva/android/started.json; echo; \$GRANTIVA emulator sessions --json; cat ~/.grantiva/android/started.json; echo; \$GRANTIVA emulator teardown --serial emulator-5556; echo teardown-exit=\$?"
# AND-018: outside-Grantiva emulator
rec AND-018 "\$GRANTIVA emulator ensure --name cov3-android-2; echo exit=\$?; cat ~/.grantiva/android/started.json; echo; \$GRANTIVA run --device emulator-5556 --no-build --flow .maestro/01-browse.yaml 2>&1 | grep -E '✓ 01|✗|Error|Using|Booting'; \$GRANTIVA run --emulator cov3-android-2 --no-build --flow .maestro/01-browse.yaml 2>&1 | grep -E '✓ 01|✗|Error|Using|Booting'; adb devices; cat ~/.grantiva/android/started.json"
# AND-011: teardown refuses hand-booted, --force kills
rec AND-011 "\$GRANTIVA emulator teardown --serial emulator-5556; echo exit=\$?; adb devices; \$GRANTIVA emulator teardown --serial emulator-5556 --force; echo exit=\$?; sleep 3; kill -0 \$(cat $S/hand-5556.pid) 2>/dev/null && echo hand-emulator-alive || echo hand-emulator-gone; adb devices"
# B-C02.2: console port busy
rec B-C02.2 "python3 -I -c \"import socket,time;s=socket.socket();s.bind(('127.0.0.1',5556));s.listen(1);open('$S/listener.pid','w').write(str(__import__('os').getpid()));time.sleep(240)\" & sleep 1; \$GRANTIVA emulator ensure --name cov3-android-2; echo exit=\$?; cat ~/.grantiva/android/started.json; echo; adb devices; s=\$(adb devices | awk '/emulator-55(58|60)/{print \$1}' | head -1); \$GRANTIVA emulator teardown --serial \$s; kill \$(cat $S/listener.pid)"
# K106: kill -9 keep-alive then teardown --force
rec B2-K106 "\$GRANTIVA emulator ensure --name cov3-android-2; T=\$(python3 -I -c 'import tempfile;print(tempfile.gettempdir())'); ls -d \$T/grantiva-* 2>/dev/null | sort > $S/k106-before.txt; $KA2 $E/B2-K106/ka emulator-5556 .maestro/01-browse.yaml; ls -d \$T/grantiva-* 2>/dev/null | sort > $S/k106-during.txt; comm -13 $S/k106-before.txt $S/k106-during.txt; kill -9 \$(cat $E/B2-K106/ka.pid); sleep 2; \$GRANTIVA emulator teardown --serial emulator-5556 --force --json; echo exit=\$?; ls -d \$T/grantiva-* 2>/dev/null | sort > $S/k106-after.txt; echo left:; comm -12 $S/k106-after.txt <(comm -13 $S/k106-before.txt $S/k106-during.txt)"
# N2-16b: teardown mid-flow, restore timing
rec N2-16 "\$GRANTIVA emulator ensure --name cov3-android-2 >/dev/null 2>&1; \$GRANTIVA run --device emulator-5556 --no-build --flow .maestro/coverage/18-long-wait.yaml > $E/N2-16/mid.out 2> $E/N2-16/mid.err & p=\$!; for i in \$(seq 1 60); do grep -q 'launchApp' $E/N2-16/mid.err && break; sleep 1; done; sleep 3; t0=\$(python3 -I -c 'import time;print(time.time())'); \$GRANTIVA emulator teardown --serial emulator-5556 --force; wait \$p; echo run-exit=\$? secs-after-teardown=\$(python3 -I -c \"import time;print(round(time.time()-\$t0,1))\"); grep -E '^Warning|^Error|restor' $E/N2-16/mid.err | cut -c1-250"
rec B2-K107-a "ls $GRANTIVA_RUNNER_HOME/locks | grep -E 'emulator-'; \$GRANTIVA emulator delete --name cov3-android-2; ls $GRANTIVA_RUNNER_HOME/locks | grep -E 'emulator-'; avdmanager list avd -c"
echo G11B-DONE
